TECH-APP-CONTROL.command:
$ErrorActionPreference = 'Stop'
$mode = Read-Host 'Enter WDAC or AppLocker (GPO/local policy)'
$since = (Get-Date).AddHours(-2)
Get-CimInstance Win32_OperatingSystem | Select-Object Caption,Version,BuildNumber
if ($mode -eq 'WDAC') {
    $ci = Join-Path $env:windir 'System32\CiTool.exe'
    if (-not (Test-Path -LiteralPath $ci)) { throw 'CiTool unavailable. Use the documented older-OS verification path; result unknown.' }
    $raw = & $ci -lp -json
    if ($LASTEXITCODE -ne 0) { throw 'CiTool failed; result unknown.' }
    $policyList = $raw | ConvertFrom-Json
    $policyList.Policies | Select-Object PolicyID,BasePolicyID,FriendlyName,Version,IsSystemPolicy,IsEnforced,IsAuthorized
    $log = 'Microsoft-Windows-CodeIntegrity/Operational'
    $ids = 3076,3077,3099
} elseif ($mode -eq 'AppLocker') {
    Get-Command Get-AppLockerPolicy,Test-AppLockerPolicy -ErrorAction Stop | Select-Object Name,Version
    Get-Service AppIDSvc | Select-Object Name,Status,StartType
    $xmlPath = Join-Path (Get-Location) ('effective-applocker-'+(Get-Date -Format 'yyyyMMdd-HHmmss')+'.xml')
    Get-AppLockerPolicy -Effective -Xml | Set-Content -LiteralPath $xmlPath -Encoding UTF8
    [xml]$policy = Get-Content -LiteralPath $xmlPath -Raw
    $policy.AppLockerPolicy.RuleCollection | Select-Object Type,EnforcementMode
    $user = Read-Host 'Standard test user: DOMAIN\name or SID (not administrator)'
    $allowed = Read-Host 'Full path to the approved benign executable'
    $denied = Read-Host 'Full path to a known-safe executable NOT authorised by this policy'
    foreach ($file in @($allowed,$denied)) {
        if (-not (Test-Path -LiteralPath $file -PathType Leaf)) { throw "Missing fixture: $file" }
        Get-FileHash -LiteralPath $file -Algorithm SHA256
        Test-AppLockerPolicy -XmlPolicy $xmlPath -Path $file -User $user
    }
    $log = 'Microsoft-Windows-AppLocker/EXE and DLL'
    $ids = 8002,8003,8004
} else { throw 'Choose WDAC or AppLocker; no test performed.' }
try {
    Get-WinEvent -FilterHashtable @{LogName=$log;Id=$ids;StartTime=$since} -ErrorAction Stop |
        Select-Object TimeCreated,Id,MachineName,Message
} catch {
    if ($_.FullyQualifiedErrorId -like 'NoMatchingEventsFound*') {
        Write-Output 'No matching events in this window. This is not a pass; run the approved test and check collection/retention.'
    } else { throw }
}

