$baselinePath = Read-Host 'Path to approved full Conditional Access policy array JSON'
$baseline = @(Get-Content -LiteralPath $baselinePath -Raw | ConvertFrom-Json)
$current = @(Read-GraphCollection 'https://graph.microsoft.com/v1.0/identity/conditionalAccess/policies')
if ($baseline.Count -eq 0 -or $current.Count -eq 0) { throw 'Empty baseline/current population; cannot assess.' }
foreach ($id in @(@($baseline | ForEach-Object { $_.id }) + @($current | ForEach-Object { $_['id'] }) | Sort-Object -Unique)) {
    $before = @($baseline | Where-Object { $_.id -eq $id })
    $after = @($current | Where-Object { $_['id'] -eq $id })
    if ($before.Count -ne 1 -or $after.Count -ne 1) { Write-Output "Review added, removed or duplicated policy: $id"; continue }
    $a = $after[0] | ConvertTo-Json -Depth 100 | ConvertFrom-Json
    foreach ($field in @('displayName','state','conditions','grantControls','sessionControls')) {
        $old = $before[0].$field | ConvertTo-Json -Depth 100 -Compress
        $new = $a.$field | ConvertTo-Json -Depth 100 -Compress
        if ($old -cne $new) { [pscustomobject]@{PolicyId=$id;Field=$field;Approved=$old;Current=$new} }
    }
}

