TECH-SUPPLIER.command:
$ErrorActionPreference = 'Stop'
function Read-GraphCollection {
    param([Parameter(Mandatory=$true)][string]$Uri)
    $seen = @{}
    do {
        if ($Uri -notmatch '^https://graph\.microsoft\.com/v1\.0/' -or $seen.ContainsKey($Uri)) {
            throw 'Unexpected Graph nextLink or repeated page. Assessment is unknown.'
        }
        $seen[$Uri] = $true
        $page = Invoke-MgGraphRequest -Method GET -Uri $Uri -OutputType Hashtable -ErrorAction Stop
        if (-not $page.ContainsKey('value')) { throw 'Expected a Graph collection; assessment is unknown.' }
        foreach ($item in $page['value']) { $item }
        $Uri = $page['@odata.nextLink']
    } while ($Uri)
}
$path = Read-Host 'Supplier access register CSV path'
$approved = @(Import-Csv -LiteralPath $path)
if ($approved.Count -eq 0) { throw 'Empty approved access register; confirm scope.' }
$filter = [uri]::EscapeDataString("userType eq 'Guest'")
$guests = @(Read-GraphCollection ('https://graph.microsoft.com/v1.0/users?$filter='+$filter+'&$select=id,userPrincipalName,accountEnabled'))
foreach ($guest in $guests) {
    $rows = @($approved | Where-Object { $_.ObjectId -eq $guest['id'] })
    $issues = @()
    if ($rows.Count -ne 1) { $issues += 'No unique approved supplier access record' }
    else {
        if (-not $rows[0].Supplier -or -not $rows[0].Owner -or -not $rows[0].RiskId) { $issues += 'Missing supplier, owner or risk reference' }
        if (-not $rows[0].AccessUntilUtc) { $issues += 'Missing access expiry' }
        elseif ([datetimeoffset]::Parse($rows[0].AccessUntilUtc) -le [datetimeoffset]::UtcNow -and $guest['accountEnabled']) { $issues += 'Expired approval with enabled guest' }
    }
    if ($issues.Count) { [pscustomobject]@{ObjectId=$guest['id'];User=$guest['userPrincipalName'];Review=($issues -join '; ')} }
}

TECH-PRIVACY.command:
$ErrorActionPreference = 'Stop'
$path = Read-Host 'Approved processing and retention register CSV path'
$rows = @(Import-Csv -LiteralPath $path)
if ($rows.Count -eq 0) { throw 'Empty processing register; cannot assess.' }
foreach ($row in $rows) {
    $issues = @()
    foreach ($field in @('DatasetId','Purpose','Owner','RetentionRule','ReviewUtc')) { if (-not $row.$field) { $issues += "Missing $field" } }
    if ($row.ReviewUtc -and [datetimeoffset]::Parse($row.ReviewUtc) -le [datetimeoffset]::UtcNow) { $issues += 'Review overdue' }
    if ($row.ContainsPersonalData -notin @('Yes','No')) { $issues += 'Unknown personal-data classification' }
    if ($row.Environment -eq 'NonProduction' -and $row.ContainsPersonalData -eq 'Yes' -and -not $row.ExceptionId) { $issues += 'Non-production personal data without exception reference' }
    if ($issues.Count) { [pscustomobject]@{Dataset=$row.DatasetId;Review=($issues -join '; ')} }
}

TECH-DEVSECOPS.command:
$ErrorActionPreference = 'Stop'
$org = Read-Host 'Azure DevOps organisation name'
$project = Read-Host 'Azure DevOps project name'
if ($org -notmatch '^[a-zA-Z0-9-]+$') { throw 'Invalid organisation name.' }
$credential = Get-Credential -Message 'Enter a short-lived read-only PAT as the password'
$basic = [Convert]::ToBase64String([Text.Encoding]::UTF8.GetBytes('audit:'+$credential.GetNetworkCredential().Password))
$headers = @{Authorization='Basic '+$basic}
$base = 'https://dev.azure.com/'+$org+'/'+[uri]::EscapeDataString($project)+'/_apis/'
try {
    (Invoke-RestMethod -Method Get -Uri ($base+'policy/configurations?api-version=7.1') -Headers $headers).value | ConvertTo-Json -Depth 100
