    (Invoke-RestMethod -Method Get -Uri ($base+'build/builds?api-version=7.1&$top=100') -Headers $headers).value | ConvertTo-Json -Depth 100
} finally { $headers.Clear(); $basic=$null; $credential=$null }

TECH-ASSURANCE.command:
$ErrorActionPreference = 'Stop'
$path = Read-Host 'Finding retest register CSV path'
$rows = @(Import-Csv -LiteralPath $path)
if ($rows.Count -eq 0) { throw 'Empty finding register; confirm assessment scope.' }
foreach ($row in $rows) {
    $issues = @()
    foreach ($field in @('FindingId','ControlId','Owner','DueUtc','TestCaseId')) { if (-not $row.$field) { $issues += "Missing $field" } }
    if ($row.Status -eq 'Closed') {
        if (-not $row.RetestUtc -or -not $row.EvidenceRef -or $row.RetestResult -ne 'Pass') { $issues += 'Closed without traceable passing retest' }
    } elseif ($row.DueUtc -and [datetimeoffset]::Parse($row.DueUtc) -lt [datetimeoffset]::UtcNow) { $issues += 'Open and overdue' }
    if ($issues.Count) { [pscustomobject]@{Finding=$row.FindingId;Review=($issues -join '; ')} }
}

TECH-PERSONNEL.command:
$ErrorActionPreference = 'Stop'
function Read-GraphCollection {
    param([Parameter(Mandatory=$true)][string]$Uri)
    $seen = @{}
    do {
        if ($Uri -notmatch '^https://graph\.microsoft\.com/v1\.0/' -or $seen.ContainsKey($Uri)) {
            throw 'Unexpected Graph nextLink or repeated page. Assessment is unknown.'
        }
        $seen[$Uri] = $true
        $page = Invoke-MgGraphRequest -Method GET -Uri $Uri -OutputType Hashtable -ErrorAction Stop
        if (-not $page.ContainsKey('value')) { throw 'Expected a Graph collection; assessment is unknown.' }
        foreach ($item in $page['value']) { $item }
        $Uri = $page['@odata.nextLink']
    } while ($Uri)
}
$path = Read-Host 'Approved personnel assurance export CSV path'
$people = @(Import-Csv -LiteralPath $path)
if ($people.Count -eq 0) { throw 'Empty personnel population.' }
$enabled = @(Read-GraphCollection 'https://graph.microsoft.com/v1.0/users?$select=id,userPrincipalName,accountEnabled,userType') | Where-Object { $_['accountEnabled'] -and $_['userType'] -eq 'Member' }
foreach ($user in $enabled) {
    $match = @($people | Where-Object { $_.ObjectId -eq $user['id'] })
    $issues = @()
    if ($match.Count -ne 1) { $issues += 'No unique personnel record: classify service/admin exception' }
    else {
        $r=$match[0]
        if ($r.ScreeningStatus -ne 'Approved' -and -not $r.ExceptionId) { $issues += 'No approved screening or exception' }
        if (-not $r.TrainingDueUtc) { $issues += 'Training due date missing' }
        elseif ([datetimeoffset]::Parse($r.TrainingDueUtc) -lt [datetimeoffset]::UtcNow) { $issues += 'Training overdue' }
        if (-not $r.RoleTrainingRef) { $issues += 'Role-specific training evidence missing' }
    }
    if ($issues.Count) { [pscustomobject]@{ObjectId=$user['id'];User=$user['userPrincipalName'];Review=($issues -join '; ')} }
}

TECH-SANITISE.command:
$ErrorActionPreference = 'Stop'
$assetPath = Read-Host 'Scoped disposal asset register CSV path'
$recordPath = Read-Host 'Sanitisation/destruction records CSV path'
$assets = @(Import-Csv -LiteralPath $assetPath)
$records = @(Import-Csv -LiteralPath $recordPath)
if ($assets.Count -eq 0 -or $records.Count -eq 0) { throw 'Missing asset/record population; cannot assess.' }
foreach ($asset in $assets) {
    if (-not $asset.Serial) { throw 'Asset without serial/unique media identifier.' }
    $matches = @($records | Where-Object { $_.Serial -eq $asset.Serial })
    $issues = @()
    if ($matches.Count -ne 1) { $issues += 'No unique disposal record' }
    else {
        foreach ($field in @('Method','CompletedUtc','Operator','VerificationRef','Destination','CustodyRef')) { if (-not $matches[0].$field) { $issues += "Missing $field" } }
    }
    if ($issues.Count) { [pscustomobject]@{Serial=$asset.Serial;Review=($issues -join '; ')} }
}

TECH-PHYSICAL.command:
$ErrorActionPreference = 'Stop'
$approvalPath = Read-Host 'Physical-access approvals CSV path'
$accessPath = Read-Host 'Sampled badge events CSV path'
$approvals = @(Import-Csv -LiteralPath $approvalPath)
$events = @(Import-Csv -LiteralPath $accessPath)
if ($approvals.Count -eq 0 -or $events.Count -eq 0) { throw 'Missing approvals/events; cannot assess.' }
foreach ($event in $events) {
    if (-not $event.BadgeId -or -not $event.Zone -or -not $event.EventUtc) { throw 'Incomplete badge event.' }
    if ($event.Result -ne 'Granted') { continue }
    $time = [datetimeoffset]::Parse($event.EventUtc)
    $valid = @($approvals | Where-Object {
        $_.BadgeId -eq $event.BadgeId -and $_.Zone -eq $event.Zone -and
        $_.StartUtc -and $_.EndUtc -and [datetimeoffset]::Parse($_.StartUtc) -le $time -and [datetimeoffset]::Parse($_.EndUtc) -gt $time
    })
    if ($valid.Count -eq 0) { [pscustomobject]@{Badge=$event.BadgeId;Zone=$event.Zone;Time=$event.EventUtc;Review='Granted event without matching valid approval'} }
}

AD-CHECK-04.command:
$ErrorActionPreference = 'Stop'
$dc = Read-Host 'FQDN of the intended domain controller'
$root = Get-ADRootDSE -Server $dc

$objects = @(Get-ADObject -Server $dc -SearchBase $root.defaultNamingContext -LDAPFilter '(|(msDS-AllowedToDelegateTo=*)(msDS-AllowedToActOnBehalfOfOtherIdentity=*))' -Properties sAMAccountName,userAccountControl,'msDS-AllowedToDelegateTo','msDS-AllowedToActOnBehalfOfOtherIdentity')
foreach ($obj in $objects) {
    $obj | Select-Object DistinguishedName,sAMAccountName,userAccountControl,'msDS-AllowedToDelegateTo'
    $bytes = $obj.'msDS-AllowedToActOnBehalfOfOtherIdentity'
    if ($bytes) {
        $descriptor = [System.Security.AccessControl.RawSecurityDescriptor]::new([byte[]]$bytes,0)
        $descriptor.DiscretionaryAcl | Select-Object SecurityIdentifier,AceType,AccessMask,AceFlags
    }
}
